import { useAuth } from "@/_core/hooks/useAuth";
import { getLoginUrl } from "@/const";
import { trpc } from "@/lib/trpc";
import {
  ArrowRight, BarChart3, Brain, Calendar, CheckCircle,
  KeyRound, Lock, Shield, TrendingUp, Users, Zap,
} from "lucide-react";
import { useState } from "react";
import { Link, useLocation } from "wouter";
import { toast } from "sonner";

const HERO_BG = "/manus-storage/russell-capital-city-night_0cb0b970.jpeg";

const FEATURES = [
  { icon: Brain, title: "Strategy Engine", desc: "Roth conversion ladders, IUL projections, and real estate depreciation modeled in seconds." },
  { icon: BarChart3, title: "CRM + Pipeline", desc: "Track every deal from lead to close with stage-aware smart coaching prompts at each step." },
  { icon: Users, title: "Team Workspace", desc: "Invite advisors, analysts, and viewers. Role-based access with full audit logging." },
  { icon: Shield, title: "Knowledge Library", desc: "Ground strategy output in your approved messaging, objection guides, and compliance rules." },
  { icon: Zap, title: "Smart Auto-Closer", desc: "Stage-aware closing scripts generated on demand for every deal in your pipeline." },
  { icon: CheckCircle, title: "Investor Demo Mode", desc: "Seeded scenarios for App Store review, investor walkthroughs, and advisor activation." },
];

// Default Calendly URL — can be overridden via workspace branding or env
const CALENDLY_URL = "https://calendly.com/samtheinsuranceman-1/30min";

function formatAum(value: number): string {
  if (value >= 1_000_000_000) return `$${(value / 1_000_000_000).toFixed(1)}B`;
  if (value >= 1_000_000) return `$${(value / 1_000_000).toFixed(1)}M`;
  if (value >= 1_000) return `$${(value / 1_000).toFixed(0)}K`;
  return `$${value.toLocaleString()}`;
}

/* ─── Client Portal Token Login ────────────────────────────────────────────── */
function ClientLoginSection() {
  const [token, setToken] = useState("");
  const [, navigate] = useLocation();
  const [isValidating, setIsValidating] = useState(false);
  const [error, setError] = useState("");

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = token.trim();
    if (!trimmed) {
      setError("Please enter your portal access code.");
      return;
    }
    setError("");
    setIsValidating(true);
    // Navigate directly — the ClientPortalView page handles invalid tokens
    navigate(`/client-portal/${trimmed}`);
  };

  return (
    <section className="container py-20">
      <div className="max-w-2xl mx-auto">
        <div className="rc-card relative overflow-hidden">
          {/* Decorative accent */}
          <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-[#22c55e] via-[#22c55e]/60 to-transparent" />

          <div className="flex flex-col md:flex-row items-start gap-8 pt-4">
            {/* Left — description */}
            <div className="flex-1">
              <div className="flex items-center gap-3 mb-4">
                <div className="w-10 h-10 rounded-xl bg-[#22c55e]/12 border border-[#22c55e]/20 flex items-center justify-center">
                  <KeyRound size={18} className="text-[#22c55e]" />
                </div>
                <h2 className="text-xl font-bold text-white" style={{ fontFamily: "DM Sans, sans-serif" }}>
                  Client Portal Access
                </h2>
              </div>
              <p className="text-sm text-[#7a95b8] leading-relaxed mb-4">
                Your advisor has shared a secure access code with you. Enter it below to view your financial plan, documents, upcoming meetings, and portfolio summary.
              </p>
              <div className="flex items-center gap-2 text-xs text-[#7a95b8]">
                <Lock size={12} className="text-[#22c55e]" />
                <span>Read-only access — your data is encrypted and secure</span>
              </div>
            </div>

            {/* Right — form */}
            <div className="w-full md:w-80">
              <form onSubmit={handleSubmit} className="space-y-3">
                <div>
                  <label className="block text-xs text-[#7a95b8] mb-1.5 font-medium">Portal Access Code</label>
                  <input
                    type="text"
                    className="rc-input w-full text-sm"
                    placeholder="e.g. abc123def456..."
                    value={token}
                    onChange={(e) => { setToken(e.target.value); setError(""); }}
                    autoComplete="off"
                    spellCheck={false}
                  />
                  {error && <p className="text-red-400 text-xs mt-1">{error}</p>}
                </div>
                <button
                  type="submit"
                  className="rc-btn rc-btn-primary w-full justify-center text-sm py-2.5"
                  disabled={isValidating}
                >
                  {isValidating ? (
                    <span className="flex items-center gap-2">
                      <span className="animate-spin h-4 w-4 border-2 border-white border-t-transparent rounded-full" />
                      Validating...
                    </span>
                  ) : (
                    <span className="flex items-center gap-2">
                      Access My Portal <ArrowRight size={14} />
                    </span>
                  )}
                </button>
              </form>
              <p className="text-xs text-[#7a95b8]/60 mt-3 text-center">
                Don't have a code? Contact your financial advisor.
              </p>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

/* ─── Book a Consultation CTA ──────────────────────────────────────────────── */
function ConsultationSection() {
  const [showCalendly, setShowCalendly] = useState(false);

  return (
    <section className="container py-20">
      <div className="rc-card text-center max-w-3xl mx-auto py-12 relative overflow-hidden">
        {/* Background pattern */}
        <div className="absolute inset-0 opacity-5">
          <div className="absolute top-4 left-8 w-32 h-32 rounded-full border border-[#22c55e]" />
          <div className="absolute bottom-4 right-8 w-48 h-48 rounded-full border border-[#22c55e]" />
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 rounded-full border border-[#22c55e]" />
        </div>

        <div className="relative z-10">
          <div className="flex items-center justify-center gap-3 mb-6">
            <div className="w-12 h-12 rounded-xl bg-[#22c55e]/12 border border-[#22c55e]/20 flex items-center justify-center">
              <Calendar size={22} className="text-[#22c55e]" />
            </div>
          </div>

          <h2 className="text-2xl md:text-3xl font-bold text-white mb-3" style={{ fontFamily: "DM Sans, sans-serif" }}>
            Book a Free Consultation
          </h2>
          <p className="text-[#7a95b8] mb-8 max-w-lg mx-auto leading-relaxed">
            Discover how Russell Capital Systems™' advanced strategies can optimize your tax position,
            maximize Roth conversions, and build tax-free retirement income. Schedule a 30-minute
            discovery call with one of our senior advisors.
          </p>

          <div className="flex flex-col sm:flex-row items-center justify-center gap-4 mb-6">
            <a
              href={CALENDLY_URL}
              target="_blank"
              rel="noopener noreferrer"
              className="rc-btn rc-btn-primary text-base px-8 py-3 rounded-xl shadow-lg shadow-[#22c55e]/20"
              onClick={(e) => {
                // Try inline popup first, fallback to new tab
                e.preventDefault();
                setShowCalendly(true);
              }}
            >
              <Calendar size={16} /> Schedule Now
            </a>
            <a
              href="tel:+18005551234"
              className="rc-btn text-base px-8 py-3 rounded-xl border border-white/20 text-white hover:bg-white/10 transition-colors"
            >
              Or Call Us Directly
            </a>
          </div>

          <div className="flex flex-wrap items-center justify-center gap-6 text-xs text-[#7a95b8]">
            <span className="flex items-center gap-1.5"><CheckCircle size={12} className="text-[#22c55e]" /> No obligation</span>
            <span className="flex items-center gap-1.5"><CheckCircle size={12} className="text-[#22c55e]" /> 30-minute call</span>
            <span className="flex items-center gap-1.5"><CheckCircle size={12} className="text-[#22c55e]" /> Personalized strategy review</span>
          </div>
        </div>

        {/* Calendly inline modal */}
        {showCalendly && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm">
            <div className="bg-[#0b1628] border border-[#12233e] rounded-2xl w-full max-w-3xl max-h-[90vh] overflow-hidden shadow-2xl">
              <div className="flex items-center justify-between p-4 border-b border-[#12233e]">
                <h3 className="text-white font-semibold">Schedule Your Consultation</h3>
                <button
                  onClick={() => setShowCalendly(false)}
                  className="text-[#7a95b8] hover:text-white transition-colors text-xl leading-none"
                >
                  &times;
                </button>
              </div>
              <div className="p-4">
                <iframe
                  src={`${CALENDLY_URL}?hide_gdpr_banner=1&background_color=0b1628&text_color=c8d8ec&primary_color=22c55e`}
                  width="100%"
                  height="600"
                  frameBorder="0"
                  title="Schedule a consultation"
                  className="rounded-lg"
                />
              </div>
            </div>
          </div>
        )}
      </div>
    </section>
  );
}

/* ─── Main Landing Page ────────────────────────────────────────────────────── */
export default function Landing() {
  const { isAuthenticated } = useAuth();
  const plansQuery = trpc.billing.plans.useQuery();

  // Fetch real platform metrics from the public demo.data endpoint
  const demoQuery = trpc.demo.data.useQuery(undefined, { staleTime: 60_000 });
  const metrics = demoQuery.data?.metrics;

  const METRICS = [
    { value: metrics ? formatAum(metrics.totalAum) : "$47.8M", label: "Assets Under Management" },
    { value: metrics ? `${metrics.openOpportunities}` : "28", label: "Active Opportunities" },
    { value: "12+", label: "Strategy Models" },
    { value: metrics ? `${metrics.aiAlerts}` : "14", label: "Strategy Alerts" },
  ];

  return (
    <div className="min-h-screen bg-[#060f20] text-[#c8d8ec]">
      {/* Nav - transparent over hero */}
      <nav className="absolute top-0 left-0 right-0 z-50">
        <div className="container flex items-center justify-between h-16">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-lg bg-[#22c55e]/20 border border-[#22c55e]/30 flex items-center justify-center">
              <span className="text-[#22c55e] font-bold text-sm">RCS</span>
            </div>
            <span className="font-bold text-white text-lg" style={{ fontFamily: "DM Sans, sans-serif" }}>Russell Capital Systems™</span>
          </div>
          <div className="hidden md:flex items-center gap-6 text-sm">
            <a href="#client-login" className="text-white/70 hover:text-white transition-colors">Client Login</a>
            <a href="#consultation" className="text-white/70 hover:text-white transition-colors">Book Consultation</a>
            <Link href="/pricing" className="text-white/70 hover:text-white transition-colors">Pricing</Link>
          </div>
          {isAuthenticated ? (
            <Link href="/portal/dashboard" className="rc-btn rc-btn-primary text-sm">
              Go to Dashboard <ArrowRight size={14} />
            </Link>
          ) : (
            <Link href="/portal/dashboard" className="rc-btn rc-btn-primary text-sm">
              Enter Dashboard <ArrowRight size={14} />
            </Link>
          )}
        </div>
      </nav>

      {/* Hero — city skyline background, centered brand */}
      <section
        className="relative min-h-[90vh] flex flex-col items-center justify-center text-center overflow-hidden"
        style={{
          backgroundImage: `url(${HERO_BG})`,
          backgroundSize: "cover",
          backgroundPosition: "center 58%",
        }}
      >
        {/* Gradient overlays for readability */}
        <div className="absolute inset-0 bg-[linear-gradient(180deg,rgba(2,10,18,.9)_0%,rgba(2,12,20,.46)_42%,rgba(4,15,24,.84)_76%,#060f20_100%)]" />
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_74%,rgba(34,197,94,.25),transparent_30%),radial-gradient(circle_at_84%_35%,rgba(16,185,129,.13),transparent_30%),linear-gradient(90deg,rgba(1,7,13,.48),transparent_32%,transparent_68%,rgba(1,7,13,.48))] mix-blend-screen" />
        <div className="absolute inset-0 bg-emerald-950/20 mix-blend-color" />
        <div className="absolute bottom-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-emerald-400/50 to-transparent" />

        <div className="relative z-10 px-4 max-w-3xl mx-auto">
          {/* Brand icon */}
          <div className="flex items-center justify-center gap-3 mb-6">
            <div className="w-12 h-12 rounded-xl bg-[#22c55e]/20 border border-[#22c55e]/30 flex items-center justify-center">
              <span className="text-[#22c55e] font-bold text-xl">RCS</span>
            </div>
          </div>

          <h1
            className="text-5xl md:text-7xl font-extrabold text-white leading-tight mb-4 drop-shadow-[0_8px_30px_rgba(0,0,0,.75)]"
            style={{ fontFamily: "DM Sans, sans-serif" }}
          >
            Russell Capital Systems™
          </h1>

          <p className="text-lg md:text-xl text-emerald-300 font-semibold tracking-[0.08em] mb-4 drop-shadow-[0_0_18px_rgba(34,197,94,.4)]">
            Turn Capital Into Income&trade;
          </p>

          <p className="text-base md:text-lg text-white/70 mb-10 max-w-xl mx-auto leading-relaxed drop-shadow-[0_4px_14px_rgba(0,0,0,.8)]">
            We help high-net-worth individuals and families convert trapped capital into tax-efficient
            retirement income through advanced Roth conversion strategies, IUL optimization,
            and institutional-grade real estate modeling.
          </p>

          {/* Three CTAs */}
          <div className="flex flex-col sm:flex-row items-center justify-center gap-4">
            {isAuthenticated ? (
              <Link
                href="/portal/clients"
                className="rc-btn rc-btn-primary text-base px-8 py-3 rounded-xl shadow-lg shadow-[#22c55e]/20"
              >
                Create Client Plan
              </Link>
            ) : (
              <Link
                href="/portal/clients"
                className="rc-btn rc-btn-primary text-base px-8 py-3 rounded-xl shadow-lg shadow-[#22c55e]/20"
              >
                Create Client Plan
              </Link>
            )}
            <a
              href="#consultation"
              className="rc-btn text-base px-8 py-3 rounded-xl border border-[#22c55e]/30 text-[#22c55e] hover:bg-[#22c55e]/10 transition-colors"
            >
              <Calendar size={16} /> Book Consultation
            </a>
            {isAuthenticated ? (
              <Link
                href="/portal/dashboard"
                className="rc-btn text-base px-8 py-3 rounded-xl border border-white/20 text-white hover:bg-white/10 transition-colors"
              >
                Go to Dashboard
              </Link>
            ) : (
              <Link
                href="/portal/dashboard"
                className="rc-btn text-base px-8 py-3 rounded-xl border border-white/20 text-white hover:bg-white/10 transition-colors"
              >
                Enter Dashboard
              </Link>
            )}
          </div>

        </div>
      </section>

      {/* Metrics bar — real data from platform */}
      <section className="border-y border-[#12233e] bg-[#0b1628]/50">
        <div className="container py-8">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
            {METRICS.map((m) => (
              <div key={m.label} className="text-center">
                <div className="rc-stat-value">{m.value}</div>
                <div className="rc-stat-label">{m.label}</div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Client Portal Login */}
      <div id="client-login">
        <ClientLoginSection />
      </div>

      {/* Features */}
      <section className="container py-20">
        <div className="text-center mb-12">
          <h2 className="text-3xl font-bold text-white mb-3" style={{ fontFamily: "DM Sans, sans-serif" }}>
            Everything an advisor team needs
          </h2>
          <p className="text-[#7a95b8] max-w-xl mx-auto">
            From first discovery call to closed deal — system-assisted, compliance-grounded, and built for scale.
          </p>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
          {FEATURES.map((f) => {
            const Icon = f.icon;
            return (
              <div key={f.title} className="rc-card group">
                <div className="w-10 h-10 rounded-xl bg-[#22c55e]/12 border border-[#22c55e]/20 flex items-center justify-center mb-4 group-hover:bg-[#22c55e]/20 transition-colors">
                  <Icon size={18} className="text-[#22c55e]" />
                </div>
                <h3 className="text-white font-semibold mb-2">{f.title}</h3>
                <p className="text-sm text-[#7a95b8] leading-relaxed">{f.desc}</p>
              </div>
            );
          })}
        </div>
      </section>

      {/* Pricing preview */}
      <section className="container py-20" id="pricing">
        <div className="text-center mb-12">
          <h2 className="text-3xl font-bold text-white mb-3" style={{ fontFamily: "DM Sans, sans-serif" }}>Simple, transparent pricing</h2>
          <p className="text-[#7a95b8]">Start with Growth, scale to Enterprise.</p>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-5xl mx-auto">
          {(plansQuery.data ?? []).map((plan) => (
            <div key={plan.slug} className={`rc-card relative ${plan.slug === "professional" ? "border-[#22c55e]/40 ring-1 ring-[#22c55e]/20" : ""}`}>
              {plan.slug === "professional" && (
                <div className="absolute -top-3 left-1/2 -translate-x-1/2">
                  <span className="rc-badge rc-badge-green text-xs">Most Popular</span>
                </div>
              )}
              <div className="mb-4">
                <div className="text-white font-bold text-lg">{plan.name}</div>
                <div className="flex items-baseline gap-1 mt-2">
                  <span className="text-3xl font-extrabold text-white">${plan.monthlyPrice.toLocaleString()}</span>
                  <span className="text-[#7a95b8] text-sm">/mo</span>
                </div>
                <div className="text-xs text-[#7a95b8] mt-1">Up to {plan.seats} seats</div>
              </div>
              <ul className="space-y-2 mb-6">
                {plan.features.map((f) => (
                  <li key={f} className="flex items-start gap-2 text-sm text-[#c8d8ec]">
                    <CheckCircle size={14} className="text-[#22c55e] mt-0.5 shrink-0" />
                    {f}
                  </li>
                ))}
              </ul>
              <Link href="/portal/dashboard" className={`rc-btn w-full justify-center ${plan.slug === "professional" ? "rc-btn-primary" : "rc-btn-secondary"}`}>
                Get Started
              </Link>
            </div>
          ))}
        </div>
      </section>

      {/* Book a Consultation */}
      <div id="consultation">
        <ConsultationSection />
      </div>

      {/* Final CTA */}
      <section className="container py-20">
        <div className="rc-card text-center max-w-2xl mx-auto py-12">
          <h2 className="text-2xl font-bold text-white mb-3" style={{ fontFamily: "DM Sans, sans-serif" }}>Ready to transform your practice?</h2>
          <p className="text-[#7a95b8] mb-6">Join advisor teams using Russell Capital Systems™ to close more HNW clients with advanced strategy.</p>
          <div className="flex flex-col sm:flex-row items-center justify-center gap-4">
            {isAuthenticated ? (
              <Link href="/portal/dashboard" className="rc-btn rc-btn-primary">
                Go to Dashboard <ArrowRight size={16} />
              </Link>
            ) : (
              <Link href="/portal/dashboard" className="rc-btn rc-btn-primary">
                Enter Dashboard <ArrowRight size={16} />
              </Link>
            )}
            <a href="#consultation" className="rc-btn rc-btn-secondary">
              <Calendar size={14} /> Book a Call
            </a>
          </div>
        </div>
      </section>

      {/* Footer */}
      <footer className="border-t border-[#12233e] py-8">
        <div className="container flex flex-col md:flex-row items-center justify-between gap-4 text-sm text-[#7a95b8]">
          <div className="flex items-center gap-2">
            <div className="w-6 h-6 rounded bg-[#22c55e]/20 flex items-center justify-center">
              <span className="text-[#22c55e] font-bold text-xs">RCS</span>
            </div>
            <span>Russell Capital Systems™ &copy; {new Date().getFullYear()}. All rights reserved.</span>
            <span className="text-xs text-[#4a6585] block mt-1">www.RussellCapitalSystems.com is owned by Russell Holdings Management LLC. Russell Capital Systems™ is a registered trademark.</span>
          </div>
          <div className="flex gap-6">
            <Link href="/privacy" className="hover:text-white transition-colors">Privacy</Link>
            <Link href="/terms" className="hover:text-white transition-colors">Terms</Link>
            <Link href="/support" className="hover:text-white transition-colors">Support</Link>
          </div>
        </div>
      </footer>
    </div>
  );
}
